"""Emit rtl/log_rom.sv from lut_model.rom_table. Run: python3 model/gen_rom.py"""
import os
import sys

sys.path.insert(0, os.path.dirname(__file__))
from lut_model import rom_table

KS = range(2, 11)
HERE = os.path.dirname(os.path.abspath(__file__))

lines = [
    "// GENERATED by model/gen_rom.py from model/lut_model.py -- do not edit.",
    "// ROM[i] = round(log2(1 + (i+0.5)/2^K) * 2^(K+2)), clipped to 2^(K+2)-1.",
    "// Address: the K most significant mantissa bits. Output: K+2 bit fraction in [0,1).",
    "module log_rom #(",
    "  parameter int K = 6",
    ") (",
    "  input  logic [K-1:0]   addr,",
    "  output logic [K+1:0]   q",
    ");",
    "  generate",
]
for j, k in enumerate(KS):
    c = k + 2
    tbl = rom_table(k)
    kw = "if" if j == 0 else "else if"
    lines.append(f"    {kw} (K == {k}) begin : g_k{k}")
    lines.append(f"      localparam logic [{c-1}:0] T [0:{(1<<k)-1}] = '{{")
    ent = [f"{c}'d{int(v)}" for v in tbl]
    for i in range(0, len(ent), 8):
        lines.append("        " + ", ".join(ent[i:i+8]) + ("," if i + 8 < len(ent) else ""))
    lines.append("      };")
    lines.append("      always_comb q = T[addr];")
    lines.append("    end")
lines += [
    "    else begin : g_bad",
    "      // K outside 2..10 is not generated: fail elaboration instead of silently",
    "      // synthesising a zero table.",
    "      initial $fatal(1, \"log_rom: unsupported K=%0d\", K);",
    "    end",
    "  endgenerate",
    "endmodule",
]
out = os.path.join(HERE, "..", "rtl", "log_rom.sv")
open(out, "w").write("\n".join(lines) + "\n")
print("wrote", os.path.normpath(out))
